// Error Alert formatter (for Error Trigger workflow)
// Naprawiono: CHAT_ID ustawiony na prawidlowy identyfikator administratora
const DEFAULT_CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID';
// ID administratora: stala konfiguracja (zmienne n8n wymagaja licencji platnej).
const CHAT_ID = DEFAULT_CHAT_ID;
// Publiczny host instancji. Ustaw po wdrozeniu na VM (Oracle).
const INSTANCE_URL = '';

function tsPL(d){
  try { return new Date(d).toLocaleString('pl-PL',{ timeZone:'Europe/Warsaw', hour12:false }); }
  catch(e){ return d || ''; }
}

const data = $json || {};
const wf   = data.workflow   || {};
const exec = data.execution  || {};
const err  = data.error      || {};
const last = data.lastNodeExecuted || err.node?.name || err.node || '';

const errMsg =
  err.message ||
  err.description ||
  err.cause?.message ||
  (Array.isArray(err.errors) && err.errors[0]?.message) ||
  '-';

const stackFirst = String(err.stack || err.cause?.stack || '').split('\n')[0] || '';
const execUrl = (INSTANCE_URL && wf.id && exec.id) ? `${INSTANCE_URL}/workflow/${wf.id}/executions/${exec.id}` : null;

const lines = [];
lines.push('❗️Błąd w workflow n8n');
lines.push(`Workflow: ${wf.name || '-'} (#${wf.id || '-'})`);
lines.push(`Execution: ${exec.id || '-'} | mode: ${exec.mode || '-'}${exec.status ? ' | status: '+exec.status : ''}`);
if (exec.startedAt)  lines.push(`Start: ${tsPL(exec.startedAt)}`);
if (exec.finishedAt) lines.push(`Koniec: ${tsPL(exec.finishedAt)}`);
lines.push(`Node: ${last || '-'}`);
lines.push(`Error: ${errMsg}`);
if (stackFirst) lines.push(`Stack: ${stackFirst}`);
if (execUrl)   lines.push(`🔗 ${execUrl}`);

return [{
  json: {
    chat_id: CHAT_ID,
    text: lines.join('\n')
  }
}];
